int binary(int a,int b,int op){if(a>b)swap(a,b);U key=((U)a<<33)|((U)b<<1)|op;auto it=bins.find(key);if(it!=bins.end())return it->second;Sig x=signals[a].s,y=signals[b].s;int r=intern(op?Sig{x.p|y.p,x.n|y.n}:Sig{x.p&y.p,x.n&y.n});if(signals[r].op<0){signals[r].op=op;signals[r].pa=a;signals[r].pb=b;}bins.emplace(key,r);return r;}
int action(int a,int g){if(signals[a].acts[g]>=0)return signals[a].acts[g];int op=signals[a].op,pa=signals[a].pa,pb=signals[a].pb;int b;if(op==2)b=neg(action(pa,g));else if(op<2&&op>=0)b=binary(action(pa,g),action(pb,g),op);else {cerr<<"bad recipe "<<a<<" op="<<op<<"\n";abort();}signals[a].acts[g]=b;return b;}
vector<int> canonical(const vector<int>&v,array<int,D>&){vector<int>best=v;for(int g=1;g<(int)autos.size();g++){vector<int>w;for(int a:v)w.push_back(action(a,g));sort(w.begin(),w.end());if(w<best)best=move(w);}return best;}


bool viable(const vector<int>&v,const vector<int>&rest,int a,int b,const Sig&z,int k,int t){
 if((z.p==Bits{}&&z.n==Bits{})||(z.p==top&&z.n==top))return false;
 int id=lookupSig(z);if(id>=0&&binary_search(v.begin(),v.end(),id))return false;
 Bits cover=t>0?(z.p^z.n):(z.p&~z.n);for(int q:rest)cover=cover|signals[q].sep[t>0];
 for(int keep=0;keep<(b<0?2:4);keep++){
  if(rest.size()+1+__builtin_popcount((unsigned)keep)>(unsigned)(k-t+1))continue;
  Bits c=cover;if(keep&1)c=c|signals[a].sep[t>0];if(keep&2)c=c|signals[b].sep[t>0];if(c==top)return true;
 }
 return false;
}
bool search(vector<int>v,int k,int t,array<int,D> free,vector<array<int,D>> liveExpr);
bool attempt(const vector<int>&v,const vector<int>&rest,int a,int b,int g,int k,int t,int kind,array<int,D> free,const vector<array<int,D>>& liveExpr){
 if(g==0||g==1||binary_search(v.begin(),v.end(),g))return false;

 array<int,D> gexpr;int ia=lower_bound(v.begin(),v.end(),a)-v.begin(),ib=b<0?-1:lower_bound(v.begin(),v.end(),b)-v.begin();
 for(int q=0;q<D;q++){if(int fe=freeExpr(proj(g,q),q);fe!=-100)gexpr[q]=fe;else{bool found=false;for(int j=0;j<(int)v.size();j++)if(proj(g,q)==proj(v[j],q)){gexpr[q]=liveExpr[j][q];found=true;break;}if(!found)gexpr[q]=makeExpr(kind,liveExpr[ia][q],ib<0?-100:liveExpr[ib][q]);}}
 for(int keep=0;keep<(b<0?2:4);keep++){
  int n=rest.size()+1+__builtin_popcount((unsigned)keep);if(n>k-t+1)continue;
  Bits cover=signals[g].sep[t>0];for(int q:rest)cover=cover|signals[q].sep[t>0];
  if(keep&1)cover=cover|signals[a].sep[t>0];if(keep&2)cover=cover|signals[b].sep[t>0];
  if(!(cover==top))continue;
  vector<int>w=rest;w.push_back(g);if(keep&1)w.push_back(a);if(keep&2)w.push_back(b);sort(w.begin(),w.end());branches++;
  vector<array<int,D>> nex;for(int z:w)nex.push_back(z==g?gexpr:liveExpr[lower_bound(v.begin(),v.end(),z)-v.begin()]);
  if(search(w,k,t,free,nex)){cerr<<"move k="<<k+1<<" t="<<t+(kind==2)<<" op="<<kind<<" a="<<a<<" b="<<b<<" g="<<g<<" keep="<<keep<<"\n";return true;}
  if(stopped)return false;
 }
 return false;
}
bool search(vector<int>v,int k,int t,array<int,D> free,vector<array<int,D>> liveExpr){
 nodes++;depths[k]++;
 if((nodes&65535)==0){double elapsed=chrono::duration<double>(chrono::steady_clock::now()-started).count();struct rusage usage;getrusage(RUSAGE_SELF,&usage);if(elapsed>seconds||nodes>maxnodes||usage.ru_maxrss>4000000){cerr<<"stop rssKB="<<usage.ru_maxrss<<" sec="<<elapsed<<" nodes="<<nodes<<"\n";stopped=true;return false;}if((nodes&1048575)==0)cerr<<"progress nodes="<<nodes<<" sec="<<elapsed<<" failed="<<failed.size()<<" signals="<<signals.size()<<" bins="<<bins.size()<<" expressions="<<expressions.size()<<" rssKB="<<usage.ru_maxrss<<"\n";}
 if(v.size()==1&&v[0]==goal)return true;
 if(k==0||t>k||v.size()>(unsigned)(k-t+1))return false;
 for(int q=0;q<D;q++){int c=0;vector<int> roots;for(int j=0;j<(int)v.size();j++){c+=pconstant(proj(v[j],q));roots.push_back(liveExpr[j][q]);}if(expressionCost(roots)+k-c<(q<3?13:q<12?11:10)){prefixDepth[k]++;return false;}}
 array<int,D> dummy{};auto cv=canonical(v,dummy);auto key=packState(cv,k,t);if(failed.count(key)){hits++;cacheDepth[k]++;return false;}uniqueDepth[k]++;
 int n=v.size();
 // Binary steps first consume both operands, then retain where budget permits.
 for(int a=0;a<n;a++)for(int b=a+1;b<n;b++){
  vector<int>rest;for(int i=0;i<n;i++)if(i!=a&&i!=b)rest.push_back(v[i]);
  for(int op=0;op<2;op++){Sig x=signals[v[a]].s,y=signals[v[b]].s;Sig z=op?Sig{x.p|y.p,x.n|y.n}:Sig{x.p&y.p,x.n&y.n};if(!viable(v,rest,v[a],v[b],z,k-1,t))continue;int g=binary(v[a],v[b],op);if(attempt(v,rest,v[a],v[b],g,k-1,t,op,free,liveExpr))return true;if(stopped)return false;}
 }
 if(t>0)for(int a=0;a<n;a++){
  vector<int>rest=v;rest.erase(rest.begin()+a);Sig x=signals[v[a]].s;Sig z{x.p^top,x.n^top};if(!viable(v,rest,v[a],-1,z,k-1,t-1))continue;int g=neg(v[a]);if(attempt(v,rest,v[a],-1,g,k-1,t-1,2,free,liveExpr))return true;if(stopped)return false;
 }
 failed.insert(move(key));return false;
}
int main(int argc,char**argv){
 seconds=argc>1?atof(argv[1]):30;maxnodes=argc>2?strtoull(argv[2],0,10):10000000;int maxk=argc>3?atoi(argv[3]):15;int initialt=argc>4?atoi(argv[4]):0;
 vector<pair<int,int>> E={{0,1},{1,2},{2,3},{3,4},{4,0},{0,5},{1,6},{2,7},{3,8},{5,7},{6,8},{8,5}};
 auto f=[&](int x){for(auto [a,b]:E)if((x>>a&1)&&(x>>b&1))return true;return false;};
 vector<int>ind,mis;for(int x=0;x<512;x++)if(!f(x))ind.push_back(x);for(int x:ind){bool maximal=true;for(int i=0;i<9;i++)if(!(x>>i&1)&&!f(x|(1<<i)))maximal=false;if(maximal)mis.push_back(x);}
 set<pair<int,int>> pairset;for(int y:ind)for(int i=0;i<9;i++)if(f(y^(1<<i)))pairset.emplace(y^(1<<i),y);for(auto [a,b]:E){pairset.emplace((1<<a)|(1<<b),0);for(int y:mis)pairset.emplace((1<<a)|(1<<b),y);}
 vector<pair<int,int>>pairs(pairset.begin(),pairset.end());cerr<<"pairs="<<pairs.size()<<" independent="<<ind.size()<<" maximal="<<mis.size()<<"\n";if(pairs.size()>W*64)return 3;
 for(int j=0;j<(int)pairs.size();j++)top.a[j/64]|=1ULL<<(j%64);
 intern({{}, {}});intern({top,top});goal=intern({top,{}});vector<int>root;
 for(int i=0;i<9;i++){Sig s;for(int j=0;j<(int)pairs.size();j++){if(pairs[j].first>>i&1)s.p.a[j/64]|=1ULL<<(j%64);if(pairs[j].second>>i&1)s.n.a[j/64]|=1ULL<<(j%64);}root.push_back(intern(s));}
 raw=root;
 array<int,9> perm;for(int i=0;i<9;i++)perm[i]=i;
 bool adjacency[9][9]{};for(auto [i,j]:E)adjacency[i][j]=adjacency[j][i]=true;
 do {bool ok=true;for(int i=0;i<9;i++)for(int j=0;j<9;j++)if(adjacency[i][j]!=adjacency[perm[i]][perm[j]])ok=false;if(ok)autos.push_back(perm);}while(next_permutation(perm.begin(),perm.end()));
 cerr<<"automorphisms="<<autos.size()<<"\n";if(autos.size()>12)return 4;
 for(int g=0;g<(int)autos.size();g++){for(int i=0;i<3;i++)signals[i].acts[g]=i;for(int i=0;i<9;i++)signals[raw[i]].acts[g]=raw[autos[g][i]];}
 int markers[3]={4,6,7};for(const auto&p:autos){array<int,D> f;for(int i=0;i<3;i++)for(int j=0;j<3;j++)if(p[markers[j]]==markers[i])f[i]=j;autoFree.push_back(f);}
 vector<array<int,D>> initialExpr;for(int a:root){array<int,D>e;for(int q=0;q<D;q++)e[q]=freeExpr(proj(a,q),q);initialExpr.push_back(e);}
 started=chrono::steady_clock::now();bool ans=search(root,maxk,initialt,{0,0,0},initialExpr);double elapsed=chrono::duration<double>(chrono::steady_clock::now()-started).count();
 cout<<"result="<<(stopped?"UNKNOWN":ans?"FOUND":"EXCLUDED")<<" k="<<maxk<<" t="<<initialt<<" sec="<<elapsed<<" nodes="<<nodes<<" hits="<<hits<<" branches="<<branches<<" failed="<<failed.size()<<" signals="<<signals.size()<<" bins="<<bins.size()<<" expressions="<<expressions.size()<<"\n";
 for(int i=0;i<32;i++)if(depths[i])cout<<"depth "<<i<<" nodes "<<depths[i]<<" unique "<<uniqueDepth[i]<<" prefix "<<prefixDepth[i]<<" cached "<<cacheDepth[i]<<"\n";
}
